package com.smartspend.service;
import com.smartspend.dao.UserDAO;import com.smartspend.model.User;import com.smartspend.util.*;import java.sql.SQLException;
public class AuthService {private final UserDAO dao=new UserDAO(); public User login(String email,String pass)throws Exception{if(!ValidationUtil.email(email)||pass==null||pass.isBlank())throw new IllegalArgumentException("Enter a valid email and password.");User u=dao.findByEmail(email.trim().toLowerCase());if(u==null||!PasswordUtil.verify(pass,u.getPasswordHash()))throw new IllegalArgumentException("Invalid email or password.");return u;} public void register(String name,String email,String pass,String confirm)throws Exception{if(name==null||name.isBlank())throw new IllegalArgumentException("Name cannot be empty.");if(!ValidationUtil.email(email))throw new IllegalArgumentException("Enter a valid email.");if(!ValidationUtil.password(pass))throw new IllegalArgumentException("Password must contain at least 8 characters.");if(!pass.equals(confirm))throw new IllegalArgumentException("Passwords do not match.");if(dao.findByEmail(email.trim().toLowerCase())!=null)throw new IllegalArgumentException("An account with this email already exists.");User u=new User();u.setName(name.trim());u.setEmail(email.trim().toLowerCase());u.setPasswordHash(PasswordUtil.hash(pass));dao.create(u);}}
